package com.fixmer.mared.technology.server.setup;
import com.fixmer.genesis.technology.server.remote.*;
import com.fixmer.mared.gui2.framework.screen.MaredScreen;
import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.components.*;import net.minecraft.client.gui.screens.*;import net.minecraft.network.chat.Component;
import java.nio.file.Path;import java.util.*;
/** Same commands for a local host and a Maop-authorized remote player; no remote filesystem paths. */
public final class FolderUpdateScreen118 extends MaredScreen {
 private final Screen previous;private final String folder;private final boolean remote;private final Object connection;private EditBox label;private int left,w,top,scroll,maxScroll;private final Map<String,Button> actions=new LinkedHashMap<>();
 public FolderUpdateScreen118(Screen previous,String folder,boolean remote){super(tr("title"));this.previous=previous;this.folder=folder;this.remote=remote;connection=net.minecraft.client.Minecraft.getInstance().getConnection();}
 private static Component tr(String k,Object...a){return Component.translatable("mared.folder118."+k,a);}
 private String root(){try{return ServerApp104.root(Path.of(folder)).toString();}catch(Exception invalid){return "";}}
 private boolean connected(){return !remote||connection==minecraft.getConnection();}
 private Map<String,String> state(){if(remote)return DedicatedPanelService75.remote();var d=new TreeMap<String,String>();var j=DedicatedPanelService75.local();for(var e:j.entrySet())if(e.getValue().isJsonPrimitive())d.put(e.getKey(),e.getValue().getAsString());return d;}
 private void save(){if(label==null)return;var p=DedicatedPanelService75.preferences();p.addProperty("label",label.getValue().trim());DedicatedPanelService75.save(p);}
 private void request(String action){if(!connected())return;save();String value=label.getValue().trim();if(!value.matches("[A-Za-z0-9_-]{1,40}"))return;if(remote)DedicatedPanelService75.request(action,value);else DedicatedPanelService75.host("command",root(),action.toLowerCase(Locale.ROOT).replace('_','-'),"",value);}
 private Button button(String text,int x,int y,int size,Runnable callback){return addRenderableWidget(Button.builder(tr(text),b->callback.run()).bounds(x,y,size,20).build());}
 @Override protected void init(){actions.clear();w=Math.max(100,Math.min(560,width-24));left=(width-w)/2;int y=38,half=(w-4)/2;
  label=addRenderableWidget(new EditBox(font,left+96,y,w-96,20,tr("release")));label.setMaxLength(40);String value="r2";try{value=DedicatedPanelService75.preferences().get("label").getAsString();}catch(Exception ignored){}label.setValue(value);y+=28;
  if(!remote){int third=(w-8)/3;button("publication",left,y,third,()->{save();minecraft.setScreen(new PublicationScreen79(this,root()));});button("https",left+third+4,y,third,()->minecraft.setScreen(new HttpsScreen78(this,root())));button("renew120",left+2*(third+4),y,third,()->minecraft.setScreen(new RenewalScreen85(this,root())));y+=26;}
  actions.put("STAGE",button("stage",left,y,w,()->request("STAGE")));y+=26;
  actions.put("COMMIT",button("commit",left,y,half,()->minecraft.setScreen(new ConfirmScreen(yes->{minecraft.setScreen(this);if(yes)request("COMMIT");},tr("commit"),tr("commit_confirm")))));actions.put("CANCEL",button("cancel",left+half+4,y,half,()->request("CANCEL")));y+=26;
  actions.put("CONTINUE_WAIT",button("wait",left,y,half,()->request("CONTINUE_WAIT")));actions.put("CLOSE",button("close",left+half+4,y,half,()->minecraft.setScreen(new ConfirmScreen(yes->{minecraft.setScreen(this);if(yes)request("CLOSE");},tr("close"),tr("close_confirm")))));top=y+30;button("back",left,height-26,w,this::onClose);tick();
 }
 @Override public void tick(){if(label==null)return;if(connected())DedicatedPanelService75.poll(!remote,remote?"":root());boolean enabled=connected()&&!DedicatedPanelService75.busy()&&(remote||!root().isBlank());var s=state();boolean fresh=false;try{long age=System.currentTimeMillis()-Long.parseLong(s.getOrDefault("updated","0"));fresh=age>=-30000&&age<=10000;}catch(Exception ignored){}com.google.gson.JsonObject control=new com.google.gson.JsonObject();try{control=com.google.gson.JsonParser.parseString(s.getOrDefault("control","{}")).getAsJsonObject();}catch(Exception ignored){}
  String phase=control.has("phase")?control.get("phase").getAsString():"";boolean pending=control.has("folder118"),commitReady=false,admitted=control.has("admission")&&control.get("admission").getAsBoolean();
  try{commitReady=phase.equals("PREPARING")&&control.get("pending").getAsInt()==0&&control.get("accepted").getAsInt()>0&&control.get("prepared").getAsInt()==control.get("accepted").getAsInt();}catch(Exception ignored){}
  for(var e:actions.entrySet()){boolean available=switch(e.getKey()){case "STAGE"->!pending&&!"true".equals(s.get("busy"));case "COMMIT"->commitReady;case "CANCEL"->pending&&!phase.equals("COMMITTED");case "CLOSE"->admitted;case "CONTINUE_WAIT"->phase.equals("COMMITTED");default->false;};e.getValue().active=enabled&&fresh&&available&&(!remote||DedicatedPanelService75.canRemote88(e.getKey()));}}
 @Override public void onClose(){save();minecraft.setScreen(previous);}@Override public boolean isPauseScreen(){return false;}@Override public boolean mouseScrolled(double x,double y,double dx,double dy){scroll=Math.max(0,Math.min(maxScroll,scroll+(int)(-dy*22)));return true;}
 @Override public void render(GuiGraphics g,int mx,int my,float dt){g.fill(0,0,width,height,0xF0151820);g.drawCenteredString(font,title,width/2,12,0xFFFFFFFF);g.drawString(font,tr("release"),left,44,0xFFCCD0DC,false);var lines=new ArrayList<Component>();lines.add(tr("help"));var s=state();lines.add(tr("state",s.getOrDefault("phase","READING"),DedicatedPanelService75.result()));String error=s.getOrDefault("failureCode","");if(!error.isBlank())lines.add(Component.literal(error));
  try{var control=com.google.gson.JsonParser.parseString(s.getOrDefault("control","{}")).getAsJsonObject();if(control.has("phase")&&control.get("phase").getAsString().equals("PREPARING"))lines.add(tr("consent",control.get("accepted").getAsString(),control.get("original").getAsString(),control.get("prepared").getAsString()));else if(control.has("total"))lines.add(tr("progress",control.get("installed").getAsString(),control.get("total").getAsString(),control.get("needed").getAsString()));if(control.has("progress81")&&control.getAsJsonObject("progress81").get("stalled").getAsBoolean())lines.add(tr("stalled"));}catch(Exception ignored){}
  if(!connected())lines.add(tr("connection_changed"));var rows=new ArrayList<net.minecraft.util.FormattedCharSequence>();for(var line:lines)rows.addAll(font.split(line,Math.max(1,w-8)));int bottom=Math.max(top,height-34),step=font.lineHeight+3;maxScroll=Math.max(0,rows.size()*step-(bottom-top));scroll=Math.min(scroll,maxScroll);if(bottom>top){g.enableScissor(left,top,left+w,bottom);int y=top-scroll;for(var row:rows){if(y+step>=top&&y<bottom)g.drawString(font,row,left,y,0xFFCCD0DC,false);y+=step;}g.disableScissor();}super.render(g,mx,my,dt);
 }
}
